package dev.veltraph.client.combat.ghost;
import java.util.List;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class GhostSourceCoordinateRefillTest {
    private static void waitForDemand(GhostSourceWalkDemandCapture<?,?> capture){long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(!capture.hasPendingRequiredReads()&&System.nanoTime()<end)Thread.onSpinWait();assertTrue(capture.hasPendingRequiredReads(),"actual worker demand must exist");}
    @Test void realEnteredWorkerPublishesItsNextRequiredCellAndSamePumpConsumesIt() throws Exception {
        var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();var active=new AtomicBoolean(true);var handoffs=new AtomicInteger();var nextDemandAllowed=new CountDownLatch(1);
        var worker=CompletableFuture.supplyAsync(()->{try{int first=capture.require(1);try{if(!nextDemandAllowed.await(2,TimeUnit.SECONDS))throw new IllegalStateException("handoff not entered");}catch(InterruptedException e){throw new IllegalStateException(e);}return first+capture.require(2);}finally{active.set(false);}});
        try{waitForDemand(capture);assertEquals(2,capture.pumpCoordinate(100,()->0,()->true,k->k,active::get,()->{handoffs.incrementAndGet();nextDemandAllowed.countDown();long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(2);while(!capture.hasPendingRequiredReads()&&active.get()&&System.nanoTime()<end)Thread.onSpinWait();}));assertEquals(3,worker.get(2,TimeUnit.SECONDS));assertTrue(handoffs.get()>0);assertEquals(2,capture.cachedDiagnostic().nativeReads());}
        finally{capture.revoke();}
    }
    @Test void ordinaryApiStillReturnsImmediatelyAfterTheExistingQueueEmpties(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.prefetch(List.of(1));assertEquals(1,capture.pump(100,()->0,()->true,k->k));assertEquals(0,capture.pendingReads());}
    @Test void queuedOrColdWorkerCannotSpendARefillHandoff(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.primeRequired(List.of(1));var turns=new AtomicInteger();assertEquals(1,capture.pumpCoordinate(100,()->0,()->true,k->k,()->false,turns::incrementAndGet));assertEquals(0,turns.get());}
    @Test void noSuccessfulNativePublicationCannotYieldForAnActiveWorker(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();var turns=new AtomicInteger();assertEquals(0,capture.pumpCoordinate(100,()->0,()->true,k->k,()->true,turns::incrementAndGet));assertEquals(0,turns.get());}
    @Test void completionDuringHandoffStopsBeforeAnotherDemandRead(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.prefetch(List.of(1));var active=new AtomicBoolean(true);var turns=new AtomicInteger();assertEquals(1,capture.pumpCoordinate(100,()->0,()->true,k->k,active::get,()->{turns.incrementAndGet();capture.primeRequired(List.of(2));active.set(false);}));assertEquals(1,turns.get());assertFalse(capture.alreadyObserved(2));}
    @Test void revocationDuringHandoffClearsDemandWithoutAnotherNativeRead(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.prefetch(List.of(1));var current=new AtomicBoolean(true);var reads=new AtomicInteger();assertEquals(1,capture.pumpCoordinate(100,()->0,current::get,k->{reads.incrementAndGet();return k;},()->true,()->{capture.primeRequired(List.of(2));current.set(false);}));assertEquals(1,reads.get());assertEquals(GhostSourceWalkDemandCapture.State.REVOKED,capture.state());assertFalse(capture.valid());assertEquals(0,capture.pendingReads());}
    @Test void budgetExpiryDuringHandoffStopsWithNextDemandStillUnobserved(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.prefetch(List.of(1));var clock=new AtomicLong();assertEquals(1,capture.pumpCoordinate(100,clock::get,()->true,k->k,()->true,()->{capture.primeRequired(List.of(2));clock.set(100);}));assertFalse(capture.alreadyObserved(2));}
    @Test void zeroOrBackwardClockCannotCauseUnboundedRefillTurns(){for(boolean backwards:new boolean[]{false,true}){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.prefetch(List.of(1));var turns=new AtomicInteger();var clock=new AtomicLong();assertEquals(1,capture.pumpCoordinate(100,()->backwards?clock.decrementAndGet():0,()->true,k->k,()->true,turns::incrementAndGet));assertEquals(GhostSourceWalkDemandCapture.MAX_COORDINATE_REFILL_HANDOFFS,turns.get());}}
    @Test void continuouslyQueuedExactDemandsAlsoHaveAFiniteZeroClockSlice(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.primeRequired(List.of(0));var reads=new AtomicInteger();assertEquals(GhostSourceWalkDemandCapture.MAX_COORDINATE_PUMP_TURNS,capture.pumpCoordinate(100,()->0,()->true,k->{reads.incrementAndGet();capture.primeRequired(List.of(k+1));return k;},()->true,()->{}));assertEquals(GhostSourceWalkDemandCapture.MAX_COORDINATE_PUMP_TURNS,reads.get());assertEquals(GhostSourceWalkDemandCapture.State.CAPTURING,capture.state());}
    @Test void unavailableUnusedFutureIsNotARouteFailureOrASuccessfulRefill(){var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();capture.primeRequired(List.of(1));var turns=new AtomicInteger();assertEquals(0,capture.pumpCoordinate(100,()->0,()->true,k->{throw new IllegalStateException("unavailable");},()->true,turns::incrementAndGet));assertEquals(0,turns.get());assertEquals(GhostSourceWalkDemandCapture.State.CAPTURING,capture.state());assertThrows(CompletionException.class,()->capture.require(1));assertEquals(GhostSourceWalkDemandCapture.State.FAILED,capture.state());}
    @Test void requiredReadFailureRetainsExceptionalFutureAndFailsCapture() throws Exception {var capture=new GhostSourceWalkDemandCapture<Integer,Integer>();var worker=CompletableFuture.supplyAsync(()->capture.require(1));try{waitForDemand(capture);assertEquals(0,capture.pumpCoordinate(100,()->0,()->true,k->{throw new IllegalStateException("native failure");},()->true,()->fail("failed publication cannot handoff")));assertThrows(ExecutionException.class,()->worker.get(2,TimeUnit.SECONDS));assertEquals(GhostSourceWalkDemandCapture.State.FAILED,capture.state());assertFalse(capture.valid());}finally{capture.revoke();}}
    @Test void realSolverTaskStateDistinguishesEnteredQueuedCancelledAndFinishedWorkers() throws Exception {
        var entered=new CountDownLatch(2);var release=new CountDownLatch(1);var resolved=new AtomicInteger();
        java.util.function.Supplier<Integer> blocker=()->{entered.countDown();try{if(!release.await(2,TimeUnit.SECONDS))throw new IllegalStateException("release timeout");return 1;}catch(InterruptedException e){throw new IllegalStateException(e);}};
        var first=GhostSourceWalkSolverExecutor.submit(blocker,()->{});var second=GhostSourceWalkSolverExecutor.submit(blocker,()->{});GhostSourceWalkSolverExecutor.Task<Integer> queued=null;
        try{assertTrue(entered.await(2,TimeUnit.SECONDS));assertTrue(first.executing());assertTrue(second.executing());queued=GhostSourceWalkSolverExecutor.submit(()->2,resolved::incrementAndGet);assertFalse(queued.executing());queued.cancel();assertFalse(queued.executing());assertEquals(1,resolved.get());release.countDown();assertEquals(1,first.future().get(2,TimeUnit.SECONDS));assertEquals(1,second.future().get(2,TimeUnit.SECONDS));assertFalse(first.executing());assertFalse(second.executing());}
        finally{release.countDown();first.cancel();second.cancel();if(queued!=null&&!queued.future().isDone())queued.cancel();}
    }
}
